# keep SOURCE_STMT_RE (line start only): their measured edge counts depend on it (SMA-605).
UV_SOURCE_STMT_RE = re.compile(
    r"""(?m)(?:^|[;&|({!]|\b(?:then|do|else)\b)\s*(?:source|\.)\s+(?!as\s+\$[A-Za-z_])["']?([^"'\s;&|)]+)["']?"""
