            for env_name in sorted(dict((proj.get("task_env") or {}).get(name) or {})):
                if env_name in ("UV_PROJECT_ENVIRONMENT", "VIRTUAL_ENV"):
                    rows.append(f"{target}: the task `env` sets {env_name}")
            for desc in uv_mutations(blob):
