SEP = re.compile(r"(?:&&|\|\||[;|)`]).*$")


def approved(line, m):
    """`None` when the `uv` at `m` is an approved form, else a reason."""
    before = line[:m.start()].rstrip()
    if before.endswith("command -v") and re.match(r"\s*(?:>|$|\s*2>)", line[m.end():] + " "):
        return None
    rest = SEP.sub("", line[m.end():])  # one invocation: cut at the first separator
    words = rest.split()
    if words[:1] == ["build"] and len(words) == 1:
        return None
    if words[:1] != ["run"]:
        return f"verb {words[:1]!r} is not approved"
    i, opts = 1, []
    while i < len(words) and words[i].startswith("-"):
        w = words[i]
        if w in FLAGS:
            opts.append(w)
            i += 1
        elif w in VALUED and i + 1 < len(words) and WORD.match(words[i + 1]):
            opts.append(w)
            i += 2
        elif w == "--reinstall-package" and words[i + 1:i + 2] == ["paigasus-py-bindings"]:
            opts.append(w)
            i += 2
        else:
            return f"option {w!r} is not approved"
    if "--reinstall-package" in opts and "--isolated" not in opts:
        return "--reinstall-package without --isolated"
    if i >= len(words) or not WORD.match(words[i]):
        return f"no plain command word after the options ({words[i:i+1]!r})"
    return None


def scan(text):
    text = text.replace("\\\n", "  \n")  # keep line numbers: continuation becomes blank + newline
    # join continuations for matching: process logical lines
    rows = []
    logical, start = [], 1
    raw = text.split("\n")
    # rebuild logical lines from the ORIGINAL text with continuations
    return raw


