    return out


total = []
for pid in sorted(projects):
    proj = projects[pid]
    for name in sorted(proj.get("invocations") or {}):
        blob = proj["invocations"][name]
        if not blob:
            continue
        target = f"{pid}:{name}"
        for ln, why, line in rows_for(blob):
            total.append(("BLOB", target, ln, why, line))
        paths = []
        for ref in c.task_script_refs(projects, root, target):
            paths.extend(c._uv_script_closure(ref, root))
        for rel in sorted(set(c.PROJECT_SCRIPT_REF_RE.findall(blob))):
            paths.extend(c._uv_script_closure((root / proj["source_dir"] / rel).resolve(), root))
        for p in dict.fromkeys(paths):
            for ln, why, line in rows_for(p.read_text()):
                total.append((str(p.relative_to(root)), target, ln, why, line))

uniq = {}
for where, target, ln, why, line in total:
    key = (where if where != "BLOB" else f"BLOB {target}", ln)
    uniq.setdefault(key, (why, line, set()))[2].add(target)
print(f"option-2 rows (unique script lines / blob lines): {len(uniq)}")
for (where, ln), (why, line, ts) in sorted(uniq.items()):
    print(f"  {where}:{ln} [{why}] {line[:140]}")

