#!/bin/bash
# Print open, not-outdated CodeRabbit threads of PR 459 as JSON lines, then the latest review bodies' size.
pr=459; owner=SMK1085; repo=paigasus-core
resp=$(gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='
  query($owner:String!,$repo:String!,$pr:Int!){
    repository(owner:$owner,name:$repo){
      pullRequest(number:$pr){
        reviewThreads(first:100){
          nodes{ id isResolved isOutdated
            comments(first:1){ nodes{ databaseId body path line author{ login } } } }
        }
      }
    }
  }')
printf '%s' "$resp" | jq -c '.data.repository.pullRequest.reviewThreads.nodes[]
  | select(.isResolved == false and .isOutdated == false)
  | select(.comments.nodes[0].author.login | test("coderabbit"; "i"))
  | { threadId: .id, commentId: .comments.nodes[0].databaseId,
      path: .comments.nodes[0].path, line: .comments.nodes[0].line,
      body: .comments.nodes[0].body }'

